from fractions import Fraction
from itertools import product
from math import sqrt


def fair_value(outcome_fn, n_dice):
    """Exact average of outcome_fn(roll) over every
    roll of n_dice dice. A roll is a tuple, e.g. (3, 6)."""
    rolls = list(product(range(1, 7), repeat=n_dice))
    return Fraction(sum(outcome_fn(r) for r in rolls), len(rolls))


def sd_of_sum(n):
    """Standard deviation of the total of n fair dice."""
    return sqrt(Fraction(35, 12) * n)
